input.shapes:
@prefix dom: <https://minimal.example/ns/domain#> .
@prefix sh: <http://www.w3.org/ns/shacl#> .
@prefix shp: <https://minimal.example/ns/domain-shapes#> .

shp:EngineShape
    a sh:NodeShape ;
    sh:property shp:EngineControlled ;
    sh:targetClass dom:Engine .

shp:EngineControlled
    a sh:PropertyShape ;
    sh:message "Every engine needs a controller."@en ;
    sh:minCount 1 ;
    sh:path dom:controlled-by ;
    sh:severity sh:Violation .

input.vocabulary:
@prefix asc: <https://w3id.org/agentic-system-core/ns#> .
@prefix dom: <https://minimal.example/ns/domain#> .
@prefix owl: <http://www.w3.org/2002/07/owl#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

asc:Concept
    a owl:Class .

asc:Episode
    a owl:Class .

asc:Cluster
    a owl:Class .

asc:uses
    a owl:ObjectProperty .

skos:definition
    a owl:AnnotationProperty .

<https://minimal.example/ns/domain>
    a owl:Ontology ;
    rdfs:label "Minimal domain vocabulary" .

dom:Engine
    a owl:Class ;
    rdfs:label "Engine" ;
    rdfs:subClassOf asc:Concept ;
    skos:definition "A machine that turns fuel into thrust."@en .

dom:controlled-by
    a owl:ObjectProperty ;
    rdfs:label "controlled by" ;
    rdfs:subPropertyOf asc:uses ;
    owl:inverseOf dom:controls ;
    skos:definition "This engine is run by the target controller."@en .

dom:controls
    a owl:ObjectProperty ;
    rdfs:label "controls" ;
    rdfs:subPropertyOf asc:uses ;
    owl:inverseOf dom:controlled-by ;
    skos:definition "This controller runs the target engine."@en .
